style.css:
@-moz-document domain("docs.google.com") {
/* 
       MAXIDENT Palette Variables 
       #FF3898 (Baby Pink) 
       #000000 (Black)
       #FFFFFF (White)
       #CFCFCF (Light Gray)
       #858585 (gray)
    */
    
    /* Document workspace background styling */
    body.stage-light, 
    #docs-chrome, 
    .docs-navigation-tab-strip {
        background-color:   #FF3898 !important;
        background-image: 
            linear-gradient(90deg, rgba(118, 177, 167, 0.4) 2px, transparent 2px),
            linear-gradient(0deg, rgba(244, 180, 196, 0.6) 3px, transparent 3px),
            linear-gradient(90deg, rgba(255, 255, 255, 0.3) 1px, transparent 1px) !important;
        background-size: 15px 40px, 8px 12px, 23px 5px !important;
        background-position: 0 0, 4px 2px, -2px 1px !important;
    }

    /* Target the primary editor container background */
    #kix-appview-wrapper {
        background: #000000 !important;
        background-image: 
            linear-gradient(45deg, #f4b4c4 25%, transparent 25%), 
            linear-gradient(-45deg, #f4b4c4 25%, transparent 25%), 
            linear-gradient(45deg, transparent 75%, #f4b4c4 75%), 
            linear-gradient(-45deg, transparent 75%, #76b1a7 75%) !important;
        background-size: 4px 4px !important;
    }

    /* Google Docs Header Toolbar */
    #docs-header,
    .docs-material #docs-header {
        background-color: #000000 !important;
        border-bottom: 2px solid #858585 !important;
    }

    /* Subtle overlay line simulating a tracking glitch over the controls */
    div#docs-bars::after {
        content: "";
        position: absolute;
        top: 50%;
        left: 0;
        width: 100%;
        height: 1px;
        background: rgba(255, 255, 255, 0.6);
        box-shadow: 0 2px 4px #f4b4c4;
        pointer-events: none;
    }
}
